function loadData(){try{const saved=localStorage.getItem(STORAGE_KEY);if(saved)return {...seed,...JSON.parse(saved)}}catch(e){}return cloneData(seed)}
let syncInFlight=false,syncAgain=false;
function persist(){const snapshot=JSON.stringify(data);localStorage.setItem(STORAGE_KEY,snapshot);if(location.protocol?.startsWith('http')){localStorage.setItem('novagest-sync-pending','1');syncToServer()}}
async function syncToServer(){if(!location.protocol?.startsWith('http')||!navigator.onLine)return;if(syncInFlight){syncAgain=true;return}syncInFlight=true;try{const snapshot=localStorage.getItem(STORAGE_KEY)||JSON.stringify(data);const response=await fetch('/api/bootstrap',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:JSON.parse(snapshot)})});if(!response.ok)throw new Error('sync');if(localStorage.getItem(STORAGE_KEY)===snapshot){localStorage.removeItem('novagest-sync-pending')}else syncAgain=true}catch(e){localStorage.setItem('novagest-sync-pending','1')}finally{syncInFlight=false;if(syncAgain){syncAgain=false;syncToServer()}}}
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
