function setPreviewDevice(mode){if(!['desktop','tablet','phone'].includes(mode))return;previewDevice=mode;$('#deviceFrame').dataset.device=mode;document.querySelectorAll('[data-device-mode]').forEach(button=>button.classList.toggle('active',button.dataset.deviceMode===mode))}
