function navigate(view){currentView=view;document.querySelectorAll('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumb').textContent=titles[view]||view;$('#sidebar').classList.remove('open');render()}
$('#menuButton').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#profileButton').addEventListener('click',()=>{if(confirm('¿Cerrar la sesión de demostración?')){sessionStorage.removeItem('novagest-session');$('#loginScreen').classList.remove('hidden')}});
function money(n){return new Intl.NumberFormat('es-DO',{style:'currency',currency:'DOP',maximumFractionDigits:0}).format(Number(n)||0)}
function dateFmt(s){if(!s)return '—';return new Intl.DateTimeFormat('es-DO',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(s+'T12:00:00'))}
function initials(s){return String(s||'').split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()}
function status(s){const cl=['Activo','Disponible','Completada','Completado','Aprobado'].includes(s)?'ok':['En proceso','Pendiente','Stock bajo','Alta'].includes(s)?'':'info';return `<span class="badge ${cl}">${esc(s)}</span>`}
function render(){if(currentView==='inicio')renderHome();else if(currentView==='configuracion')renderSettings();else if(currentView==='calendario')renderModule('eventos');else if(currentView==='reportes')renderReports();else if(currentView==='auditoria')renderAudit();else if(currentView==='api')renderApi();else renderModule(currentView)}
function renderHome(){const totalSales=data.ventas.reduce((a,x)=>a+Number(x.total||0),0),low=data.inventario.filter(x=>Number(x.cantidad)<=Number(x.minimo)).length,pending=data.tareas.filter(x=>x.estado!=='Completada').length;$('#content').innerHTML=`
 <div class="welcome"><div><p class="eyebrow">${new Intl.DateTimeFormat('es-DO',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(new Date()).toUpperCase()}</p><h1>¡Buenos días, Administrador! <span>✦</span></h1><p>Aquí tienes el resumen de lo que sucede en <strong>tu organización</strong>.</p></div><button class="btn btn-primary" data-new="tareas"><span>＋</span> Crear una tarea</button></div>
 <div class="metrics">${metric('Ingresos registrados',money(totalSales),'↗','violet','De las ventas registradas')}${metric('Empleados activos',data.empleados.length,'♙','teal','En todos los departamentos')}${metric('Clientes',data.clientes.length,'♧','blue','Cuentas en tu cartera')}${metric('Pendientes por atender',pending+low,'◷','gold',`${pending} tareas · ${low} alertas de inventario`)}</div>
 <div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-head"><div><h2>Actividad de la organización</h2><p>Resumen de ventas registradas</p></div><select class="select-mini" id="chartPeriod"><option>Últimos 7 días</option><option>Este mes</option></select></div><div class="chart-area"><canvas id="salesChart" aria-label="Gráfico de actividad de ventas"></canvas></div></section>
 <section class="panel dept-panel"><div class="panel-head"><div><h2>Departamentos</h2><p>Distribución de la organización</p></div><button class="link-btn" data-view="departamentos">Ver todos →</button></div><div class="dept-list">${data.departamentos.slice(0,6).map((d,i)=>`<div class="dept-row"><span class="dept-icon" style="background:${['#eee9ff','#e3f6f3','#fff2dc','#eaf1ff','#fce9f2','#e8f5ec'][i]};color:${['#7049cc','#0d9488','#d08a08','#4d6ed0','#be5d8e','#52855c'][i]}">${['◫','♙','$','↗','✦','▤'][i]}</span><span><b>${esc(d.nombre)}</b><small>${esc(d.responsable)}</small></span><span class="dept-count">${esc(d.miembros)} pers.</span></div>`).join('')}</div><div class="panel-foot"><span>${data.departamentos.length} departamentos registrados</span><button class="link-btn" data-new="departamentos">＋ Añadir</button></div></section>
 <section class="panel activity-panel"><div class="panel-head"><div><h2>Tareas y solicitudes</h2><p>Elementos que requieren seguimiento</p></div><button class="link-btn" data-view="tareas">Ver tareas →</button></div><div class="request-list">${data.tareas.filter(x=>x.estado!=='Completada').slice(0,3).map((t,i)=>`<div class="request-row"><span class="request-mark">${i===0?'◷':'↗'}</span><span><b>${esc(t.titulo)}</b><small>${esc(t.responsable)} · ${dateFmt(t.fecha)}</small></span>${status(t.estado)}</div>`).join('')||'<div class="empty-state">No hay pendientes por atender.</div>'}</div></section>
 <section class="panel"><div class="panel-head"><div><h2>Actividad reciente</h2><p>Últimos movimientos de tu espacio</p></div><button class="link-btn" data-view="ventas">Ver ventas →</button></div><div class="activity-list">${activityRows()}</div></section></div>`;
 document.querySelectorAll('[data-new]').forEach(b=>b.addEventListener('click',()=>openForm(b.dataset.new)));drawChart();$('#chartPeriod').addEventListener('change',drawChart);}
function metric(label,value,icon,color,note){return `<article class="metric"><div class="metric-top"><span class="metric-label">${label}</span><span class="metric-icon ${color}">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></article>`}
function activityRows(){return data.ventas.slice(-3).reverse().map((v,i)=>`<div class="activity-row"><span class="activity-avatar">${initials(v.cliente)}</span><span class="activity-copy"><b>${esc(v.cliente)}</b> · venta ${esc(v.articulo)} registrada<small>${dateFmt(v.fecha)} · ${money(v.total)}</small></span></div>`).join('')||'<div class="empty-state">Todavía no hay actividad.</div>'}
function drawChart(){const c=$('#salesChart');if(!c)return;const rect=c.getBoundingClientRect(),dpr=window.devicePixelRatio||1;c.width=rect.width*dpr;c.height=rect.height*dpr;const ctx=c.getContext('2d');ctx.scale(dpr,dpr);const w=rect.width,h=rect.height,labels=$('#chartPeriod').value==='Este mes'?['1–5','6–10','11–15','16–20','21–25','26–30']:['Jue','Vie','Sáb','Dom','Lun','Mar','Mié'];let vals;if($('#chartPeriod').value==='Este mes'){const buckets=Array(6).fill(0);data.ventas.forEach(v=>{const d=new Date(v.fecha+'T12:00:00').getDate();buckets[Math.min(5,Math.floor((d-1)/5))]+=Number(v.total)});vals=buckets.map(x=>x||0)}else{vals=Array(7).fill(0);data.ventas.forEach(v=>{const ago=(new Date(todayISO()+'T12:00:00')-new Date(v.fecha+'T12:00:00'))/86400000;const n=Math.round(6-ago);if(n>=0&&n<7)vals[n]+=Number(v.total)});if(vals.every(x=>!x))vals=[45000,72000,39000,93000,67000,112000,82000]};const max=Math.max(...vals,1)*1.18,left=34,right=8,top=12,bottom=25,gw=w-left-right,gh=h-top-bottom;ctx.font='9px DM Sans';ctx.textBaseline='middle';for(let i=0;i<4;i++){const y=top+gh*i/3;ctx.strokeStyle='#efedf4';ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke();ctx.fillStyle='#9a99a9';ctx.textAlign='right';ctx.fillText(i===0?'RD$ '+Math.round(max/1000)+'k':i===3?'0':'RD$ '+Math.round(max*(1-i/3)/1000)+'k',left-7,y)}const pts=vals.map((v,i)=>({x:left+(gw*i/(vals.length-1)),y:top+gh-(v/max)*gh}));const gr=ctx.createLinearGradient(0,top,0,h-bottom);gr.addColorStop(0,'#8b5cf638');gr.addColorStop(1,'#8b5cf600');ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.lineTo(pts[pts.length-1].x,h-bottom);ctx.lineTo(pts[0].x,h-bottom);ctx.closePath();ctx.fillStyle=gr;ctx.fill();ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle='#7042dc';ctx.lineWidth=2;ctx.stroke();pts.forEach((p,i)=>{ctx.beginPath();ctx.arc(p.x,p.y,3,0,7);ctx.fillStyle='#fff';ctx.fill();ctx.strokeStyle='#7042dc';ctx.lineWidth=1.5;ctx.stroke();ctx.fillStyle='#9291a1';ctx.textAlign='center';ctx.fillText(labels[i],p.x,h-9)})}
