function renderModule(key,filter=''){const m=modules[key];if(!m)return;let rows=(data[key]||[]).filter(r=>Object.values(r).some(v=>String(v).toLowerCase().includes(filter.toLowerCase())));let extra='';if(key==='inventario'){const low=data.inventario.filter(x=>+x.cantidad<=+x.minimo).length;extra=`<div class="kpi-strip">${metric('Productos registrados',data.inventario.length,'▤','violet','En todas las categorías')}${metric('Unidades disponibles',data.inventario.reduce((a,x)=>a+(+x.cantidad||0),0),'↗','teal','Existencias registradas')}${metric('Alertas de stock bajo',low,'◷','gold','Productos bajo nivel mínimo')}</div>`}if(key==='ventas')extra=`<div class="kpi-strip">${metric('Ventas registradas',data.ventas.length,'↗','violet','Operaciones en el sistema')}${metric('Monto total',money(data.ventas.reduce((a,x)=>a+(+x.total||0),0)),'$','teal','Suma de ventas registradas')}${metric('Pendientes',data.ventas.filter(x=>x.estado!=='Completada').length,'◷','gold','Requieren seguimiento')}</div>`;
 const readonly=currentRole==='auditor';$('#content').innerHTML=`<div class="page-head"><div><p class="eyebrow">GESTIÓN · NOVAGEST</p><h1>${m.title}</h1><p>${m.description}</p></div>${readonly?'':`<button class="btn btn-primary" data-add="${key}"><span>＋</span> Nuevo ${m.singular}</button>`}</div>${extra}<section class="panel table-panel"><div class="table-tools"><span class="table-count"><b>${rows.length}</b> registros</span><input class="filter-input" id="moduleSearch" placeholder="Buscar ${m.title.toLowerCase()}..." value="${esc(filter)}" aria-label="Buscar ${m.title}"></div><table class="data-table"><thead><tr>${m.columns.map(c=>`<th>${c[1]}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map(r=>`<tr>${m.columns.map(([k])=>`<td>${k==='estado'||k==='prioridad'?status(r[k]):displayValue(k,r[k])}</td>`).join('')}<td>${readonly?'':`<button class="row-actions" aria-label="Editar registro" title="Editar" data-edit="${key}" data-id="${r.id}">✎</button> <button class="row-actions" aria-label="Eliminar registro" title="Eliminar" data-delete="${key}" data-id="${r.id}">×</button>`}</td></tr>`).join('')||`<tr><td colspan="${m.columns.length+1}"><div class="empty-state"><b>No se encontraron registros</b>Agrega el primer ${m.singular} para comenzar.</div></td></tr>`}</tbody></table></section>`;
 $('#moduleSearch').addEventListener('input',e=>renderModule(key,e.target.value));if(!readonly)$(`[data-add="${key}"]`).addEventListener('click',()=>openForm(key));document.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>openForm(key,Number(b.dataset.id))));document.querySelectorAll('[data-delete]').forEach(b=>b.addEventListener('click',()=>{if(confirm(`¿Eliminar este registro de ${m.title.toLowerCase()}?`)){const old=data[key].find(x=>x.id===Number(b.dataset.id));data[key]=data[key].filter(x=>x.id!==Number(b.dataset.id));addLog(`Eliminó un registro de ${m.title}`,m.title,old?.nombre||old?.titulo||old?.cliente||`ID ${b.dataset.id}`);persist();renderModule(key);toast('Registro eliminado.')}}));}
function renderReports(){const sum=(key,pred)=>data[key].filter(pred).length;const completed=sum('tareas',x=>x.estado==='Completada'),active=sum('empleados',x=>x.estado==='Activo'),low=sum('inventario',x=>+x.cantidad<=+x.minimo),income=data.finanzas.filter(x=>x.tipo==='Ingreso').reduce((a,x)=>a+(+x.monto||0),0),expenses=data.finanzas.filter(x=>x.tipo==='Gasto').reduce((a,x)=>a+(+x.monto||0),0);$('#content').innerHTML=`<div class="page-head"><div><p class="eyebrow">ANÁLISIS · NOVAGEST</p><h1>Reportes e indicadores</h1><p>Resumen operativo generado a partir de los registros del sistema.</p></div><button class="btn btn-primary" id="reportExport">Descargar reporte <span>↓</span></button></div><div class="metrics">${metric('Personal activo',active,'♙','violet','Colaboradores')}${metric('Ventas registradas',data.ventas.length,'↗','teal',money(data.ventas.reduce((a,x)=>a+(+x.total||0),0))+' acumulados')}${metric('Tareas completadas',completed,'☑','blue','De '+data.tareas.length+' actividades')}${metric('Alertas de inventario',low,'◷','gold','Bajo el nivel mínimo')}</div><div class="lower-grid"><section class="panel"><div class="panel-head"><div><h2>Resumen financiero</h2><p>Movimientos registrados</p></div><button class="link-btn" data-view="finanzas">Ver finanzas →</button></div><div class="request-list"><div class="request-row"><span class="request-mark">↗</span><span><b>Ingresos</b><small>Registros financieros de tipo ingreso</small></span><b style="margin-left:auto">${money(income)}</b></div><div class="request-row"><span class="request-mark">↘</span><span><b>Gastos</b><small>Registros financieros de tipo gasto</small></span><b style="margin-left:auto">${money(expenses)}</b></div><div class="request-row"><span class="request-mark">＝</span><span><b>Balance neto</b><small>Ingresos menos gastos registrados</small></span><b style="margin-left:auto">${money(income-expenses)}</b></div></div></section><section class="panel"><div class="panel-head"><div><h2>Resumen de operaciones</h2><p>Indicadores actuales</p></div></div><div class="request-list"><div class="request-row"><span class="request-mark">◷</span><span><b>Solicitudes de compra</b><small>Pendientes de aprobación</small></span>${status(sum('compras',x=>x.estado==='Pendiente')+' pendientes')}</div><div class="request-row"><span class="request-mark">◉</span><span><b>Tickets de soporte</b><small>Incidencias sin resolver</small></span>${status(sum('soporte',x=>x.estado!=='Resuelto')+' abiertos')}</div><div class="request-row"><span class="request-mark">▤</span><span><b>Documentos catalogados</b><small>Vigentes y restringidos</small></span>${status(data.documentos.length+' documentos')}</div></div></section></div>`;$('#reportExport').addEventListener('click',exportData)}
function apiRequest(method,path,body){const routeMap={departments:'departamentos',departamentos:'departamentos',employees:'empleados',empleados:'empleados',clients:'clientes',clientes:'clientes',inventory:'inventario',inventario:'inventario',sales:'ventas',ventas:'ventas',tasks:'tareas',tareas:'tareas',suppliers:'proveedores',proveedores:'proveedores',purchases:'compras',compras:'compras',finance:'finanzas',finanzas:'finanzas',tickets:'soporte',soporte:'soporte',documents:'documentos',documentos:'documentos',events:'eventos',eventos:'eventos',campaigns:'marketing',marketing:'marketing',shipments:'logistica',logistica:'logistica',legal:'legal',production:'produccion',produccion:'produccion',projects:'proyectos',proyectos:'proyectos',leave_requests:'asistencia',asistencia:'asistencia',users:'usuarios',usuarios:'usuarios'};const parts=String(path).split('?')[0].split('/').filter(Boolean);if(parts[0]!=='api')return{status:404,body:{error:'Ruta no encontrada'}};if(parts[1]==='dashboard'&&parts[2]==='summary'&&method==='GET')return{status:200,body:{empleados_activos:data.empleados.filter(x=>x.estado==='Activo').length,clientes:data.clientes.length,ventas:data.ventas.length,ventas_total:data.ventas.reduce((a,x)=>a+(+x.total||0),0),tareas_pendientes:data.tareas.filter(x=>x.estado!=='Completada').length,alertas_stock:data.inventario.filter(x=>+x.cantidad<=+x.minimo).length}};const key=routeMap[parts[1]];if(!key)return{status:404,body:{error:'Recurso no encontrado'}};const id=parts[2]?Number(parts[2]):null,rows=data[key];if(method==='GET'){const row=id?rows.find(x=>+x.id===id):rows;if(!row)return{status:404,body:{error:'Registro no encontrado'}};return{status:200,body:row}}if(currentRole==='auditor')return{status:403,body:{error:'El perfil auditor tiene acceso de solo lectura'}};if(method==='POST'&&!id){if(!body||typeof body!=='object'||Array.isArray(body))return{status:422,body:{error:'El cuerpo debe ser un objeto JSON'}};const item={...body,id:Math.max(0,...rows.map(x=>+x.id||0))+1};rows.push(item);addLog('Creó un registro',titles[key]||key,JSON.stringify(item));persist();return{status:201,body:item}}if(['PUT','PATCH'].includes(method)&&id){const item=rows.find(x=>+x.id===id);if(!item)return{status:404,body:{error:'Registro no encontrado'}};Object.assign(item,body||{});persist();return{status:200,body:item}}if(method==='DELETE'&&id){const ix=rows.findIndex(x=>+x.id===id);if(ix<0)return{status:404,body:{error:'Registro no encontrado'}};const removed=rows.splice(ix,1)[0];addLog('Eliminó un registro',titles[key]||key,String(id));persist();return{status:200,body:{eliminado:true,id:removed.id}}}return{status:405,body:{error:'Método no permitido para esta ruta'}}}
window.NovaGestAPI={request:apiRequest};
function renderApi(){$('#content').innerHTML=`<div class="page-head"><div><p class="eyebrow">DESARROLLO · NOVAGEST</p><h1>Explorador de API REST</h1><p>Prueba operaciones JSON sobre los registros locales de esta demostración.</p></div></div><section class="panel api-panel"><div class="api-warning">ⓘ API simulada en el navegador para demostración. No expone rutas HTTP reales ni sustituye la API Laravel del sistema final.</div><div class="api-controls"><select id="apiMethod" class="api-method"><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option></select><input id="apiPath" class="filter-input api-path" value="/api/dashboard/summary" aria-label="Ruta API"><button id="apiSend" class="btn btn-primary">Enviar solicitud <span>→</span></button></div><div class="api-cols"><div><label class="api-label" for="apiBody">Cuerpo JSON</label><textarea id="apiBody" class="api-body" spellcheck="false">{\n  "nombre": "Nuevo cliente",\n  "contacto": "Contacto principal",\n  "email": "cliente@empresa.do",\n  "estado": "Activo"\n}</textarea></div><div><div class="api-response-head"><span class="api-label">Respuesta</span><span class="badge ok" id="apiStatus">200 OK</span></div><pre class="api-response" id="apiResponse">Envía una solicitud para consultar la respuesta JSON.</pre></div></div><div class="api-examples"><span class="api-label">Rutas de ejemplo</span><button data-api="GET|/api/departments">GET departamentos</button><button data-api="GET|/api/clients">GET clientes</button><button data-api="POST|/api/clients">POST cliente</button><button data-api="GET|/api/dashboard/summary">GET resumen</button></div></section>`;const run=()=>{let body=null;try{if(['POST','PUT','PATCH'].includes($('#apiMethod').value))body=JSON.parse($('#apiBody').value||'{}')}catch{$('#apiStatus').textContent='422 JSON inválido';$('#apiStatus').className='badge';$('#apiResponse').textContent=JSON.stringify({error:'Revisa la sintaxis JSON del cuerpo.'},null,2);return}const result=apiRequest($('#apiMethod').value,$('#apiPath').value,body);$('#apiStatus').textContent=`${result.status} ${({200:'OK',201:'Created',403:'Forbidden',404:'Not Found',405:'Method Not Allowed',422:'Unprocessable Entity'})[result.status]||'Error'}`;$('#apiStatus').className=`badge ${result.status<300?'ok':''}`;$('#apiResponse').textContent=JSON.stringify(result.body,null,2)};$('#apiSend').addEventListener('click',run);document.querySelectorAll('[data-api]').forEach(b=>b.addEventListener('click',()=>{const [method,path]=b.dataset.api.split('|');$('#apiMethod').value=method;$('#apiPath').value=path;run()} ) )}
function renderAudit(){const logs=data.logs||[];$('#content').innerHTML=`<div class="page-head"><div><p class="eyebrow">CONTROL · NOVAGEST</p><h1>Auditoría y actividad</h1><p>Seguimiento de acciones de demostración registradas en el sistema.</p></div><button class="btn btn-light" id="auditExport">Descargar bitácora <span>↓</span></button></div><section class="panel table-panel"><div class="table-tools"><span class="table-count"><b>${logs.length}</b> eventos</span><span class="table-count">Vista de solo lectura</span></div><table class="data-table"><thead><tr><th>Usuario</th><th>Acción</th><th>Módulo</th><th>Fecha</th><th>Detalle</th></tr></thead><tbody>${logs.slice().reverse().map(x=>`<tr><td>${esc(x.usuario)}</td><td>${esc(x.accion)}</td><td>${esc(x.modulo)}</td><td>${dateFmt(x.fecha)}</td><td>${esc(x.detalle)}</td></tr>`).join('')}</tbody></table></section>`;$('#auditExport').addEventListener('click',exportData)}
function renderSettings(){$('#content').innerHTML=`<div class="page-head"><div><p class="eyebrow">PREFERENCIAS · NOVAGEST</p><h1>Configuración</h1><p>Información del espacio de trabajo y tus datos.</p></div></div><section class="panel" style="padding:20px;max-width:640px"><h2 style="font:700 14px Manrope;margin:0 0 8px">Politécnico San Valero</h2><p style="font-size:11px;color:#88879a;line-height:1.7">NovaGest reúne los registros de los módulos de demostración en este navegador. Los datos quedan guardados en este dispositivo. Puedes respaldar o restaurar la información aquí.</p><div style="display:flex;gap:9px;margin-top:17px;flex-wrap:wrap"><button class="btn btn-primary" id="exportData">Descargar copia de datos <span>↓</span></button><label class="btn btn-light" for="importData" style="cursor:pointer">Restaurar una copia</label><input type="file" id="importData" accept="application/json" hidden><button class="btn btn-light" id="resetData">Restablecer datos de ejemplo</button></div><p style="font-size:9px;color:#9998a7;margin-top:13px">Prototipo académico · Versión 1.1 · Noviembre 2026</p></section>`;$('#exportData').addEventListener('click',exportData);$('#importData').addEventListener('change',async e=>{try{const obj=JSON.parse(await e.target.files[0].text()),incoming=obj.novagest||obj;if(!incoming.departamentos||!incoming.empleados)throw Error();data={...cloneData(seed),...incoming};persist();render();toast('Copia de datos restaurada.')}catch{toast('No se pudo leer el archivo. Selecciona una copia NovaGest válida.')}});$('#resetData').addEventListener('click',()=>{if(confirm('¿Restablecer todos los datos al contenido de ejemplo? Esta acción no se puede deshacer.')){data=cloneData(seed);persist();render();toast('Los datos de ejemplo se restauraron.')}})}
function openForm(key,id=null){const m=modules[key];if(!m)return;modalKey=key;editing=id?{key,id}:null;const item=id?data[key].find(x=>x.id===id):{};$('#modalTitle').textContent=id?'Editar '+m.singular:'Nuevo '+m.singular;$('#formFields').innerHTML=m.fields.map(([name,label,type,required,options])=>{let opts=options;if(name==='departamento'&&type==='select')opts=data.departamentos.map(d=>d.nombre);if(name==='cliente'&&type==='select')opts=data.clientes.map(d=>d.nombre);return `<div class="field ${type==='textarea'?'full':''}"><label for="f_${name}">${label}${required?' *':''}</label>${type==='select'?`<select id="f_${name}" name="${name}" ${required?'required':''}><option value="">Selecciona una opción</option>${(opts||[]).map(o=>`<option ${item[name]===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input id="f_${name}" name="${name}" type="${type}" ${required?'required':''} value="${esc(item[name]??'')}" ${type==='number'?'min="0"':''}>`}</div>`}).join('');$('#recordDialog').showModal()}
$('#recordForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();if(!e.currentTarget.reportValidity())return;const form=new FormData(e.currentTarget),key=modalKey,vals=Object.fromEntries(form.entries()),old=editing?data[key].find(x=>x.id===editing.id):null;if(key==='inventario')vals.estado=Number(vals.cantidad)<=Number(vals.minimo)?'Stock bajo':'Disponible';if(key==='compras'&&vals.estado==='Recibido'&&old?.estado!=='Recibido'){const found=data.inventario.find(p=>p.nombre.toLowerCase()===String(vals.articulo).toLowerCase());if(found){found.cantidad=Number(found.cantidad)+Number(vals.cantidad);found.estado=Number(found.cantidad)<=Number(found.minimo)?'Stock bajo':'Disponible'}}if(key==='ventas'&&vals.estado==='Completada'&&old?.estado!=='Completada'){const found=data.inventario.find(p=>String(vals.articulo).toLowerCase().includes(p.nombre.toLowerCase()));if(found){if(Number(found.cantidad)<1){toast('No hay existencias para completar esta venta.');return}found.cantidad=Number(found.cantidad)-1;found.estado=Number(found.cantidad)<=Number(found.minimo)?'Stock bajo':'Disponible'}}if(editing){Object.assign(old,vals)}else{vals.id=Math.max(0,...data[key].map(x=>+x.id||0))+1;data[key].push(vals)}addLog(editing?'Actualizó un registro':'Creó un registro',modules[key].title,vals.nombre||vals.titulo||vals.articulo||vals.cliente||vals.concepto||'');persist();$('#recordDialog').close();toast(editing?'Registro actualizado.':'Registro creado correctamente.');render()});
$('#recordDialog').addEventListener('close',()=>editing=null);
document.addEventListener('click',e=>{const v=e.target.closest('[data-view]');if(v&&!v.closest('#nav')&&!v.hasAttribute('data-view'))return;if(v&&v.dataset.view)navigate(v.dataset.view)});
$('#globalSearch').addEventListener('input',e=>{const q=e.target.value.trim();if(q.length>1&&modules[currentView])renderModule(currentView,q)});$('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const q=e.target.value.trim();if(q){const keys=Object.keys(modules);const found=keys.find(k=>data[k].some(r=>Object.values(r).join(' ').toLowerCase().includes(q.toLowerCase())));if(found){navigate(found);$('#moduleSearch').value=q;renderModule(found,q)}else toast('No encontramos registros con ese término.')}}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').focus()}});
function addLog(accion,modulo,detalle){data.logs=data.logs||[];data.logs.push({id:Math.max(0,...data.logs.map(x=>+x.id||0))+1,usuario:roleInfo?.[currentRole]?.[0]||'Administrador',accion,modulo,fecha:new Date().toISOString().slice(0,10),detalle})}
function exportData(){const blob=new Blob([JSON.stringify({exportado:new Date().toISOString(),novagest:data},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='novagest-copia-datos.json';a.click();URL.revokeObjectURL(a.href);toast('Copia de datos descargada.')}
let toastTimer;function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
const roleInfo={admin:['Administrador','Dirección general'],direccion:['Dirección','Vista ejecutiva'],jefe:['Jefe de área','Gestión departamental'],empleado:['Empleado','Vista operativa'],auditor:['Auditor','Solo lectura']};
let authMode='login';
function setAuthMode(mode){authMode=mode;const registering=mode==='register';$('#registerNameField').hidden=!registering;$('#registerName').required=registering;$('#confirmPasswordField').hidden=!registering;$('#confirmPassword').required=registering;$('#keepSessionField').hidden=registering;$('#demoNote').hidden=registering;$('#authTitle').textContent=registering?'Crear cuenta nueva':'Bienvenido de vuelta';$('#authIntro').textContent=registering?'Regístrate para entrar a NovaGest como usuario.':'Ingresa a tu espacio empresarial para continuar.';$('#authSubmit').innerHTML=registering?'Crear cuenta <span>→</span>':'Iniciar sesión <span>→</span>';$('#switchAuthMode').textContent=registering?'¿Ya tienes cuenta? Iniciar sesión':'¿No tienes cuenta? Crear cuenta nueva';$('#loginForm').dataset.mode=mode;if(registering){$('#loginForm [name="email"]').value='';$('#loginForm [name="password"]').value='';$('#loginForm [name="password"]').autocomplete='new-password'}else{$('#loginForm [name="email"]').value='admin@novagest.do';$('#loginForm [name="password"]').value='Demo2026!';$('#loginForm [name="password"]').autocomplete='current-password'}}
$('#switchAuthMode').addEventListener('click',()=>setAuthMode(authMode==='login'?'register':'login'));
async function passwordDigest(password,saltHex=null){if(!crypto?.subtle||!crypto.getRandomValues)throw new Error('Este navegador no permite proteger cuentas locales. Abre NovaGest con HTTPS.');const salt=saltHex?Uint8Array.from(saltHex.match(/.{2}/g).map(x=>parseInt(x,16))):crypto.getRandomValues(new Uint8Array(16));const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt,iterations:120000},key,256);return{salt:Array.from(salt,b=>b.toString(16).padStart(2,'0')).join(''),hash:Array.from(new Uint8Array(bits),b=>b.toString(16).padStart(2,'0')).join('')}}
function localAccounts(){try{const a=JSON.parse(localStorage.getItem('novagest-users-v1')||'[]');return Array.isArray(a)?a:[]}catch(e){return []}}
function finishLogin(user,offline=false){const role=user.role==='superadmin'?'admin':(['admin','direccion','jefe','empleado','auditor'].includes(user.role)?user.role:'empleado');const display={...user,role};sessionStorage.setItem('novagest-session',offline?'offline':'database');localStorage.setItem('novagest-auth-user',JSON.stringify(display));$('#loginScreen').classList.add('hidden');$('#roleSelect').value=role;$('#roleSelect').dispatchEvent(new Event('change'));$('#profileName').textContent=display.name||'Usuario';addLog('Inició sesión','Acceso',offline?'Inicio local sin conexión':'Inicio de sesión validado');persist();return display}
async function registerAccount(email,password,name){if(name.length<2){toast('Escribe tu nombre completo.');return}if(password.length<8){toast('La contraseña debe tener al menos 8 caracteres.');return}if(password!==$('#confirmPassword').value){toast('Las contraseñas no coinciden.');return}const digest=await passwordDigest(password),accounts=localAccounts();if(accounts.some(a=>a.email===email)){toast('Ya existe una cuenta local con ese correo.');return}let user={name,email,role:'empleado'};if(location.protocol?.startsWith('http')&&!window.NOVAGEST_STATIC_DEMO){try{const r=await fetch('/api/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,email,password})});if(r.status===409){toast('Ya existe una cuenta con ese correo.');return}if(!r.ok){const error=await r.json().catch(()=>({}));throw new Error(error.error||'No se pudo crear la cuenta.')}user=(await r.json()).user||user}catch(err){if(navigator.onLine){toast(err.message||'No se pudo crear la cuenta.');return}user.localOnly=true}}else user.localOnly=true;accounts.push({name,email,passwordSalt:digest.salt,passwordHash:digest.hash,role:user.role||'empleado'});localStorage.setItem('novagest-users-v1',JSON.stringify(accounts));data.usuarios=data.usuarios||[];if(!data.usuarios.some(u=>String(u.email).toLowerCase()===email))data.usuarios.push({id:Math.max(0,...data.usuarios.map(u=>+u.id||0))+1,nombre:name,email,rol:'Empleado',departamento:'Dirección general',estado:'Activo'});setAuthMode('login');finishLogin(user,Boolean(user.localOnly));toast(user.localOnly?'Cuenta creada en este dispositivo.':'Cuenta creada correctamente.')}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;const f=new FormData(e.currentTarget),email=String(f.get('email')||'').trim().toLowerCase(),password=String(f.get('password')||''),isDemo=email==='admin@novagest.do'&&password==='Demo2026!';try{if(authMode==='register'){await registerAccount(email,password,String(f.get('registerName')||'').trim());return}const local=localAccounts().find(a=>a.email===email);if(local&&await passwordDigest(password,local.passwordSalt).then(x=>x.hash)===local.passwordHash){finishLogin({name:local.name,email,role:local.role},true);toast('Sesión iniciada en este dispositivo.');return}if(isDemo){let user={name:'Administrador',email,role:'admin'};if(location.protocol?.startsWith('http')&&!window.NOVAGEST_STATIC_DEMO){const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})});if(r.status===401){toast('Correo o contraseña incorrectos.');return}if(r.ok)user=(await r.json()).user||user;else throw new Error('servidor')}finishLogin(user,false);return}if(location.protocol?.startsWith('http')&&!window.NOVAGEST_STATIC_DEMO){const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})});if(r.status===401){toast('Correo o contraseña incorrectos.');return}if(!r.ok)throw new Error('No se pudo validar el acceso.');const result=await r.json();finishLogin(result.user||{name:email.split('@')[0],email,role:'empleado'});return}toast('Correo o contraseña incorrectos.')}catch(err){toast(navigator.onLine?(err.message||'No se pudo iniciar sesión.'):'Sin conexión. Usa una cuenta guardada en este dispositivo.')}});if(sessionStorage.getItem('novagest-session'))$('#loginScreen').classList.add('hidden');
if(location.protocol?.startsWith('http')){const pending=localStorage.getItem('novagest-sync-pending')==='1';if(pending)syncToServer();else fetch('/api/bootstrap').then(r=>{if(!r.ok)throw new Error();return r.json()}).then(async result=>{const remote=result.data||{};if(Object.values(remote).every(rows=>!rows?.length)){persist()}else{data={...data,...remote};localStorage.setItem(STORAGE_KEY,JSON.stringify(data));render()}}).catch(()=>{if(localStorage.getItem('novagest-sync-pending')!=='1')localStorage.setItem('novagest-sync-pending','1')})}
window.addEventListener('online',()=>{syncToServer();toast('Conexión restablecida. Sincronizando cambios guardados.')} );
$('#roleSelect').addEventListener('change',e=>{currentRole=e.target.value;const [name,sub]=roleInfo[currentRole];$('#profileName').textContent=name;$('#profileRole').textContent=sub;$('#profileButton .avatar').textContent=initials(name);const allowed={admin:Object.keys(titles),direccion:['inicio','departamentos','empleados','clientes','inventario','ventas','compras','proveedores','finanzas','tareas','reportes','calendario','documentos','marketing','logistica','legal','produccion','proyectos','asistencia'],jefe:['inicio','empleados','clientes','inventario','ventas','compras','proveedores','tareas','soporte','documentos','calendario','reportes','marketing','logistica','proyectos','asistencia'],empleado:['inicio','tareas','soporte','documentos','calendario','asistencia'],auditor:['inicio','reportes','auditoria','documentos']}[currentRole];document.querySelectorAll('#nav [data-view],.sidebar-bottom [data-view]').forEach(b=>b.classList.toggle('hidden',!allowed.includes(b.dataset.view)));if(!allowed.includes(currentView))navigate('inicio');else render();toast('Vista de demostración: '+sub)});
$('#notifyButton').addEventListener('click',()=>{const pending=data.tareas.filter(x=>x.estado!=='Completada').length+data.compras.filter(x=>x.estado==='Pendiente').length;toast(`Tienes ${pending} pendientes entre tareas y compras.`)});
window.addEventListener('resize',()=>{clearTimeout(chartResize);chartResize=setTimeout(drawChart,100)});if(currentRole!=='admin'){$('#roleSelect').value=currentRole;$('#roleSelect').dispatchEvent(new Event('change'))}else{render()}


